import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                        torch::Tensor weight,
                                        c10::optional<torch::Tensor> bias,
                                        int stride, int padding,
                                        int output_padding, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T, int Threads, int PVec>
__global__ void conv_transpose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int K, int stride, int padding,
    int Dout, int Hout, int Wout,
    int CinPerGroup, int CoutPerGroup)
{
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);

  const int tid = threadIdx.x;
  const int n   = blockIdx.z;
  const int co  = blockIdx.y;
  const int g   = co / CoutPerGroup;
  const int ci_start  = g * CinPerGroup;
  const int co_local  = co - g * CoutPerGroup;

  const int P_total = Dout * Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Strides (row-major, contiguous NCDHW)
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sXn = (int64_t)Cin * sXc;

  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  const int64_t sYn = (int64_t)Cout * sYc;

  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                         make_shape(Cin, D, H, Win),
                         make_stride(sXc, sXd, sXh, Int<1>{}));

  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                         make_shape(Cout, Dout, Hout, Wout),
                         make_stride(sYc, sYd, sYh, Int<1>{}));

  // Weight layout: [Cin, CoutPerGroup, K, K, K], contiguous
  const int64_t wKKK = (int64_t)K * K * K;
  const int64_t wKK  = (int64_t)K * K;
  const int64_t sWci = (int64_t)CoutPerGroup * wKKK;

  auto mW = make_tensor(make_gmem_ptr(W),
                         make_shape(Cin, CoutPerGroup, K, K, K),
                         make_stride(sWci, wKKK, wKK, (int64_t)K, Int<1>{}));

  // Shared memory weight cache for this (co) across all ci in this group
  auto sW = make_tensor(make_smem_ptr(sW_ptr),
                         make_shape(CinPerGroup, K, K, K),
                         make_stride(wKKK, wKK, (int64_t)K, Int<1>{}));

  const int total_w_elems = CinPerGroup * K * K * K;
  for (int idx = tid; idx < total_w_elems; idx += Threads) {
    int rem = idx;
    int kw = rem % K; rem /= K;
    int kh = rem % K; rem /= K;
    int kd = rem % K; rem /= K;
    int ci_local = rem;
    int ci = ci_start + ci_local;
    sW(ci_local, kd, kh, kw) = mW(ci, co_local, kd, kh, kw);
  }
  __syncthreads();

  int p_idx[PVec];
  int od_arr[PVec], oh_arr[PVec], ow_arr[PVec];
  bool p_valid[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int od = p / (Hout * Wout);
      int rem = p - od * (Hout * Wout);
      int oh = rem / Wout;
      int ow = rem - oh * Wout;
      od_arr[i] = od; oh_arr[i] = oh; ow_arr[i] = ow;
      p_valid[i] = true;
    } else {
      od_arr[i] = 0; oh_arr[i] = 0; ow_arr[i] = 0;
      p_valid[i] = false;
    }
  }

  float bval = 0.0f;
  if (Bias != nullptr) {
    bval = (float)Bias[co];
  }

  float acc[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) acc[i] = bval;

  for (int kd = 0; kd < K; ++kd) {
    for (int kh = 0; kh < K; ++kh) {
      for (int kw = 0; kw < K; ++kw) {

        int id_arr[PVec], ih_arr[PVec], iw_arr[PVec];
        bool valid[PVec];

        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
          if (!p_valid[i]) { valid[i] = false; continue; }
          int id_num = od_arr[i] + padding - kd;
          int ih_num = oh_arr[i] + padding - kh;
          int iw_num = ow_arr[i] + padding - kw;

          bool ok = true;
          int id = 0, ih = 0, iw = 0;
          if (id_num % stride != 0) ok = false;
          else { id = id_num / stride; ok = ok && (id >= 0 && id < D); }
          if (ok) {
            if (ih_num % stride != 0) ok = false;
            else { ih = ih_num / stride; ok = ok && (ih >= 0 && ih < H); }
          }
          if (ok) {
            if (iw_num % stride != 0) ok = false;
            else { iw = iw_num / stride; ok = ok && (iw >= 0 && iw < Win); }
          }
          valid[i] = ok;
          id_arr[i] = id; ih_arr[i] = ih; iw_arr[i] = iw;
        }

        for (int ci_local = 0; ci_local < CinPerGroup; ++ci_local) {
          int ci = ci_start + ci_local;
          float wval = (float)sW(ci_local, kd, kh, kw);

          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            if (!valid[i]) continue;
            float xval = (float)mX(ci, id_arr[i], ih_arr[i], iw_arr[i]);
            acc[i] += xval * wval;
          }
        }
      }
    }
  }

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    if (!p_valid[i]) continue;
    mY(co, od_arr[i], oh_arr[i], ow_arr[i]) = static_cast<T>(acc[i]);
  }
}

torch::Tensor conv_transpose3d_forward(torch::Tensor x,
                                        torch::Tensor weight,
                                        c10::optional<torch::Tensor> bias,
                                        int stride, int padding,
                                        int output_padding, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N,C,D,H,W]");
  TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout/groups, K,K,K]");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  int64_t N   = x_c.size(0);
  int64_t Cin = x_c.size(1);
  int64_t D   = x_c.size(2);
  int64_t H   = x_c.size(3);
  int64_t Win = x_c.size(4);

  TORCH_CHECK(w_c.size(0) == Cin, "weight.size(0) must equal Cin");
  int64_t CoutPerGroup = w_c.size(1);
  int64_t K = w_c.size(2);
  TORCH_CHECK(w_c.size(3) == K && w_c.size(4) == K, "kernel must be cubic");

  int64_t Cout = CoutPerGroup * groups;
  int64_t CinPerGroup = Cin / groups;
  TORCH_CHECK(CinPerGroup * groups == Cin, "Cin must be divisible by groups");

  int64_t Dout = (D - 1) * stride - 2 * padding + K + output_padding;
  int64_t Hout = (H - 1) * stride - 2 * padding + K + output_padding;
  int64_t Wout = (Win - 1) * stride - 2 * padding + K + output_padding;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  constexpr int Threads = 128;
  constexpr int PVec = 4;
  const int64_t P_total = Dout * Hout * Wout;
  const int64_t PTile = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)Cout,
      (unsigned)N
  );

  size_t smem_bytes = (size_t)CinPerGroup * K * K * K * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv_transpose3d_kernel<float, Threads, PVec><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)K, (int)stride, (int)padding,
      (int)Dout, (int)Hout, (int)Wout,
      (int)CinPerGroup, (int)CoutPerGroup
  );

